"""Embedded frontend source assets for EVN CSKH Monitor.

The installable custom component intentionally contains no ``webui`` directory.
At runtime these compact embedded assets are materialized into
``/config/evncskh/webui`` by an executor job.
"""

from __future__ import annotations

import base64
import zlib


def _decode(payload: bytes) -> bytes:
    """Decode one immutable compressed frontend payload."""
    return zlib.decompress(base64.b85decode(payload))


